#include <iostream>

int fib(int n) {
    if (n < 0) {
        std::cout << "Incorrect input";
        return -1;
    } else if (n == 0 || n == 1) {
        return n;
    } else {
        return fib(n-1) + fib(n-2);
    }
}

int main() {
    int n;
    std::cout << "Enter n: ";
    std::cin >> n;
    int result = fib(n);
    if (result != -1) {
        std::cout << "The " << n << "th Fibonacci number is " << result;
    }
    return 0;
}
```

